import 'jest';
import { deepMerge } from '../../src';

interface ITestObject {
    simpleProperty: number;
    readonly getterProperty: number;
    setterProperty: number;
    setProperty: (value: number) => void;
    dateProperty: Date;
    arrayProperty: string[];
    objectProperty: {
        foo: number;
        baz: number;
        bar: {
            baz: number;
        }
    };
    somethingNew?: object;
}

describe('The deepMerge function', () => {
    let target: ITestObject;

    beforeEach(() => {
        target = {
            simpleProperty: 1,
            get getterProperty(): number {
                return 0;
            },
            set setterProperty(value: number) {
                // Do Nothing
            },
            setProperty(_value: number): void {
                // Do Nothing
            },
            dateProperty: new Date(2000, 1, 1),
            arrayProperty: ['foo'],
            objectProperty: {
                foo: 1,
                baz: 1,
                bar: {
                    baz: 1
                }
            }
        };
    });

    it('should replace property getters in the target', () => {
        deepMerge(target, {
            get getterProperty(): number | undefined {
                return this.simpleProperty;
            }
        });

        target.simpleProperty = 2;
        expect(target.getterProperty).toEqual(2);
    });

    it('should replace property setters in the target', () => {
        deepMerge(target, {
            set setterProperty(value: number) {
                this.simpleProperty = value;
            }
        });

        target.simpleProperty = 1;
        target.setterProperty = 2;
        expect(target.simpleProperty).toEqual(2);
    });

    it('should replace functions in the target', () => {
        deepMerge(target, {
            setProperty(value: number): void {
                this.simpleProperty = value;
            }
        });

        target.simpleProperty = 1;
        target.setProperty(2);
        expect(target.simpleProperty).toEqual(2);
    });

    it('should replace date properties in the target', () => {
        const date = new Date(2010, 1, 1);

        deepMerge(target, {
            dateProperty: date
        });

        expect(target.dateProperty.getTime()).toEqual(date.getTime());
    });

    it('should replace array properties in the target', () => {
        deepMerge(target, {
            arrayProperty: ['bar']
        });

        expect(target.arrayProperty[0]).toEqual('bar');
    });

    it('should merge object properties in the target', () => {
        deepMerge(target, {
            objectProperty: {
                foo: 2
            }
        });

        expect(target.objectProperty.foo).toEqual(2);
        expect(target.objectProperty.bar).toEqual({ baz: 1 });
        expect(target.objectProperty.baz).toEqual(1);
    });

    it('should replace simple properties in the target', () => {
        deepMerge(target, {
            simpleProperty: 2
        });

        expect(target.simpleProperty).toEqual(2);
    });

    it('should add the new property when it is an object', () => {
        deepMerge(target, {
            somethingNew: {
                somethingBlue: 'blue'
            }
        });

        expect(target.somethingNew).toEqual({ somethingBlue: 'blue' });
    });

    it('should not overwrite any source objects', () => {
        const source = {
            simpleProperty: 1,
            somethingNew: {
                somethingBlue: 'blue'
            },
            objectProperty: {
                bar: {
                    baz: 1
                }
            }
        };
        const sourceTwo = {
            somethingNew: {
                somethingBlue: 'red'
            },
            objectProperty: {
                foo: 5,
                baz: 1,
                bar: {
                    baz: 4
                }
            }
        };

        const sourceDeepClone = JSON.parse(JSON.stringify(source));
        deepMerge(target, source, sourceTwo);
        expect(source.somethingNew.somethingBlue).toEqual(sourceDeepClone.somethingNew.somethingBlue);
    });
});
